from __future__ import annotations
TABLE: tuple[int, ...] = (3,5,3,73,3,5,3,7,3,5,3,13,3,5,3,19,3,5,3,7,3,5,3,13,3,5,3,37,3,5,3,7,3,5,3,13)
def witness(n: int) -> tuple[int, int]:
    """Return the assigned divisor and the exact remainder."""
    if n < 0: raise ValueError("n must be nonnegative")
    p = TABLE[n % 36]
    return p, (78557 * pow(2, n, p) + 1) % p
if __name__ == "__main__":
    for n in (0,1,3,11,27,63,1000,10000): print(n, witness(n))

from __future__ import annotations
from dataclasses import dataclass
@dataclass(frozen=True)
class Rule: residue: int; modulus: int; prime: int
RULES: tuple[Rule, ...] = (Rule(0,2,3),Rule(1,4,5),Rule(1,3,7),Rule(11,12,13),Rule(15,18,19),Rule(27,36,37),Rule(3,9,73))
def covering_rules(r: int) -> list[Rule]:
    return [q for q in RULES if r % q.modulus == q.residue]
if __name__ == "__main__":
    for r in range(36):
        rules=covering_rules(r); assert rules
        print(f"{r:2d}:", [(q.modulus,q.residue,q.prime) for q in rules])

from __future__ import annotations
from math import gcd
def compatible(a: int, m: int, b: int, n: int) -> bool:
    """Generalized Chinese-remainder criterion."""
    if not (m > 0 and n > 0): raise ValueError("moduli must be positive")
    return (a-b) % gcd(m,n) == 0
def common_member(a: int, m: int, b: int, n: int) -> int | None:
    if not compatible(a,m,b,n): return None
    for x in range((m*n)//gcd(m,n)):
        if x % m == a % m and x % n == b % n: return x
    raise RuntimeError("compatible classes must have a solution")
if __name__ == "__main__":
    for case in ((1,4,1,3),(0,2,1,4),(3,9,15,18)): print(case, common_member(*case))

