from __future__ import annotations
from dataclasses import dataclass
from math import lcm
@dataclass(frozen=True)
class Rule: residue: int; modulus: int; prime: int
def build_table(rules: list[Rule]) -> tuple[int, list[int]]:
    M=lcm(*(q.modulus for q in rules)); table=[]
    for r in range(M):
        hits=[q.prime for q in rules if r % q.modulus == q.residue]
        if not hits: raise ValueError(f"uncovered residue {r}")
        table.append(hits[0])
    return M, table

from __future__ import annotations
from dataclasses import dataclass
@dataclass(frozen=True)
class Candidate: name: str; covered: frozenset[int]
def greedy_cover(universe: set[int], candidates: list[Candidate]) -> list[Candidate]:
    remaining=set(universe); chosen=[]
    while remaining:
        best=max(candidates,key=lambda c: len(c.covered & remaining))
        if not (best.covered & remaining): raise ValueError("candidate family cannot cover universe")
        chosen.append(best); remaining -= best.covered
    return chosen

